import { MapPin, Phone, Mail } from "lucide-react";
import { Link } from "@tanstack/react-router";
import { SocialIcons } from "@/components/site/SocialIcons";
import { useSiteSettings } from "@/components/site/AdSettingsContext";
import { AttributionGuard } from "@/components/site/AttributionGuard";
import { useTranslation } from "@/lib/i18n";
import { cleanCopyright, isEnterpriseLicense, isEnterprisePlusLicense } from "@/lib/site-content";
import { useTheme } from "@/lib/theme";
import { getAccessibleLogoColor } from "@/lib/color-utils";

export function Footer() {
  const { t } = useTranslation();
  const { theme } = useTheme();
  const isDark = (theme as string) === "dark" || ((theme as string) === "system" && typeof window !== "undefined" && window.matchMedia("(prefers-color-scheme: dark)").matches);
  const s = useSiteSettings();
  const safeSecondaryColor = getAccessibleLogoColor(s.logoColorSecondary || "#dc2626", isDark, 4.5);
  const year = new Date().getFullYear();
  const rawCopyright = s.copyright || `© ${year} News Theme Media Co. All rights reserved.`;
  const copyright = cleanCopyright(rawCopyright).replace("{year}", String(year));
  const partnerHref = s.builtByUrl?.startsWith("http")
    ? s.builtByUrl
    : `https://${s.builtByUrl || "GorillaTechsolution.com"}`;

  const isEnterprise = isEnterpriseLicense(s);
  const isEnterprisePlus = isEnterprisePlusLicense(s);
  const showEventLink = s.eventFooterLinkEnabled !== false;

  const allAvailableLinks: { label: string; to?: string }[] = [
    { label: t("footer.about"), to: "/about" },
    { label: t("footer.contact"), to: "/contact" },
    { label: t("footer.workWithUs"), to: "/work-with-us" },
    { label: t("footer.submitNews"), to: "/submit-news" },
    ...(showEventLink ? [{ label: t("footer.event", "Event"), to: "/event" }] : []),
    ...(isEnterprise ? [{ label: t("footer.factCheck", "Fact Check"), to: "/fact-check" }] : []),
    ...(isEnterprise
      ? [{ label: t("footer.verifiedJournalist"), to: "/verified-journalist" }]
      : []),
    { label: t("footer.privacyPolicy"), to: "/privacy-policy" },
    { label: t("footer.terms"), to: "/terms-and-conditions" },
    { label: t("footer.cookiePolicy"), to: "/cookie-policy" },
    { label: t("footer.refundPolicy"), to: "/refund-policy" },
    { label: t("footer.disclaimer"), to: "/disclaimer" },
    { label: t("footer.editorialPolicy"), to: "/editorial-policy" },
    { label: t("footer.factCheckingPolicy", "Fact-Checking Policy"), to: "/fact-checking-policy" },
    { label: "Data Deletion Policy", to: "/data-deletion-policy" },
    { label: t("footer.dmca"), to: "/dmca" },
    { label: t("footer.subscription"), to: "/subscription" },
    { label: t("footer.archive"), to: "/archive" },
    ...(isEnterprisePlus ? [{ label: t("footer.earnPoints"), to: "/earn-points" }] : []),
  ];

  // Dynamically group all permitted links so each row contains 3 links per line
  const quickLinks: { label: string; to?: string }[][] = [];
  for (let i = 0; i < allAvailableLinks.length; i += 3) {
    quickLinks.push(allAvailableLinks.slice(i, i + 3));
  }

  const footerLight = s.footerLogoLight || s.logoLight;
  const footerDark = s.footerLogoDark || s.logoDark;
  const hasLogo = !!(footerLight || footerDark);
  const mode = s.logoDisplayMode || (hasLogo ? "both" : "text_only");

  const showLogo =
    hasLogo &&
    (mode === "logo_only" || mode === "both" || mode === "both_stacked" || mode === "logo_fit");
  const showText =
    !hasLogo || mode === "text_only" || mode === "both" || mode === "both_stacked";
  const isSideBySide = mode === "both" && showLogo && showText;

  const footerBrandName = (
    (s.logoTextPrimary !== undefined && s.logoTextPrimary !== ""
      ? `${s.logoTextPrimary} ${s.logoTextSecondary || ""}`
      : s.logoText || s.siteName) || ""
  ).trim() || "Home";

  // Split links into 2 neat categories for desktop readability and better space distribution:
  // 1. Navigation & Company Links
  const companyLinks = allAvailableLinks.slice(0, 7);
  // 2. Policies, Terms & Archives
  const legalLinks = allAvailableLinks.slice(7);

  const footerWidthClass =
    s.footerWidth === "full"
      ? "w-full px-4 sm:px-8 lg:px-12 xl:px-16"
      : s.footerWidth === "contained"
        ? "mx-auto max-w-7xl px-4"
        : "mx-auto max-w-[1600px] px-4 sm:px-8 lg:px-12";

  const dividerAccentColor = safeSecondaryColor || s.logoColorSecondary || "#dc2626";

  return (
    <footer className="border-t border-border bg-card/40 w-full overflow-hidden">
      <div className="w-full px-4 sm:px-6 md:px-8 lg:px-10 xl:px-12 py-8">
        <div className="grid gap-8 md:grid-cols-3 lg:gap-10 items-start">
          {/* Brand */}
          <div className="flex flex-col items-center text-center md:items-start md:text-left">
            <Link
              to="/"
              aria-label={footerBrandName}
              className={`inline-flex max-w-full ${
                isSideBySide
                  ? "flex-row items-center gap-3 text-left"
                  : "flex-col items-center text-center md:items-start md:text-left"
              }`}
            >
              {showLogo && footerLight && (
                <img
                  src={footerLight}
                  alt={s.logoText || "Logo"}
                  width={180}
                  height={48}
                  loading="lazy"
                  decoding="async"
                  className={`h-11 w-auto max-w-[70px] sm:max-w-[90px] object-contain shrink-0 ${
                    footerDark ? "dark:hidden" : ""
                  } ${!isSideBySide && showText ? "mb-3" : ""}`}
                />
              )}
              {showLogo && footerDark && (
                <img
                  src={footerDark}
                  alt={s.logoText || "Logo"}
                  width={180}
                  height={48}
                  loading="lazy"
                  decoding="async"
                  className={`h-11 w-auto max-w-[70px] sm:max-w-[90px] object-contain shrink-0 ${
                    footerLight ? "hidden dark:block" : ""
                  } ${!isSideBySide && showText ? "mb-3" : ""}`}
                />
              )}
              {showText && (
                <div
                  className="text-2xl uppercase leading-none min-h-[1.1em] flex items-center"
                  style={{
                    fontFamily: 'var(--font-headlines, "Noto Serif Bengali", "SolaimanLipi", serif)',
                    fontWeight: 800,
                    letterSpacing: "0.05em",
                  }}
                >
                  <span
                    style={s.logoColorPrimary ? { color: s.logoColorPrimary } : undefined}
                    className={
                      !s.logoColorPrimary || s.logoColorPrimary === "#000000"
                        ? "text-foreground dark:text-white"
                        : ""
                    }
                  >
                    {s.logoTextPrimary !== undefined && s.logoTextPrimary !== ""
                      ? s.logoTextPrimary
                      : s.logoText
                        ? s.logoText.split(" ")[0]
                        : "Today"}
                  </span>{" "}
                  <span style={{ color: dividerAccentColor }}>
                    {s.logoTextSecondary !== undefined && s.logoTextSecondary !== ""
                      ? s.logoTextSecondary
                      : s.logoText && s.logoText.split(" ").length > 1
                        ? s.logoText.split(" ").slice(1).join(" ")
                        : "Tripura"}
                  </span>
                </div>
              )}
            </Link>

            {/* Accent Divider below Logo & Site Name */}
            <div className="my-3.5 flex items-center gap-2 w-full max-w-[220px] mx-auto md:mx-0" aria-hidden="true">
              <span
                className="h-[4px] w-12 rounded-full shrink-0 shadow-xs"
                style={{ backgroundColor: dividerAccentColor }}
              />
              <span className="h-[1.5px] flex-1 bg-border/90 rounded-full" />
            </div>

            <p className="text-sm text-muted-foreground leading-relaxed mt-1">
              {s.footerNote?.trim() ||
                s.metaDescription ||
                "News Theme is an independent newsroom covering breaking news, finance, business and markets across Northeast India and beyond. Trusted, verified and editorially independent journalism."}{" "}
              <Link
                to="/about"
                aria-label={t("footer.readMoreAbout", "Read more about us")}
                className="font-semibold text-blue-600 hover:text-blue-700 hover:underline dark:text-blue-400 dark:hover:text-blue-300 ml-1 inline-block"
              >
                {t("footer.readMoreAbout", "Read more about us")}
              </Link>
            </p>
            <SocialIcons
              className="mt-4 justify-center md:justify-start"
              size="md"
              links={{
                facebook: s.facebook,
                instagram: s.instagram,
                twitter: s.twitter,
                pinterest: s.pinterest,
                tiktok: s.tiktok,
                whatsapp: s.whatsapp,
                youtube: s.youtube,
                linkedin: s.linkedin,
                telegram: s.telegram,
              }}
            />
          </div>

          {/* Quick Links (Single Centered Block as in reference image) */}
          <div className="text-center">
            <p className="text-sm font-bold uppercase tracking-widest text-foreground">
              {t("footer.quickLinks")}
            </p>
            {/* Elegant Accent Divider below Quick Links */}
            <div className="my-3 flex items-center justify-center gap-2 w-full max-w-[160px] mx-auto" aria-hidden="true">
              <span
                className="h-[3.5px] w-10 rounded-full shrink-0 shadow-xs"
                style={{ backgroundColor: dividerAccentColor }}
              />
              <span className="h-[1.5px] flex-1 bg-border/90 rounded-full" />
            </div>

            <div className="mt-3 space-y-2 text-xs sm:text-[13px] leading-relaxed text-muted-foreground">
              {quickLinks.map((row, i) => (
                <div
                  key={i}
                  className="flex flex-wrap items-center justify-center gap-x-3.5 sm:gap-x-4 md:gap-x-5 gap-y-1"
                >
                  {row.map((l) =>
                    l.to ? (
                      <Link
                        key={l.label}
                        to={l.to}
                        className="whitespace-nowrap hover:text-foreground hover:underline transition-colors py-0.5"
                      >
                        {l.label}
                      </Link>
                    ) : (
                      <a
                        key={l.label}
                        href="#"
                        className="whitespace-nowrap hover:text-foreground hover:underline transition-colors py-0.5"
                      >
                        {l.label}
                      </a>
                    ),
                  )}
                </div>
              ))}
            </div>
          </div>

          {/* Connect */}
          <div className="text-center md:text-right">
            <p className="text-sm font-bold uppercase tracking-widest text-foreground">
              {t("footer.connectWithUs")}
            </p>
            {/* Elegant Accent Divider below Connect With Us */}
            <div className="my-3 flex items-center justify-center md:justify-end gap-2 w-full max-w-[180px] mx-auto md:ml-auto md:mr-0" aria-hidden="true">
              <span className="h-[1.5px] flex-1 bg-border/90 rounded-full hidden md:block" />
              <span
                className="h-[3.5px] w-10 rounded-full shrink-0 shadow-xs"
                style={{ backgroundColor: dividerAccentColor }}
              />
              <span className="h-[1.5px] flex-1 bg-border/90 rounded-full md:hidden" />
            </div>

            <ul className="mt-3 space-y-2.5 text-sm text-muted-foreground">
              <li className="flex items-start justify-center gap-2 md:justify-end">
                <MapPin className="mt-0.5 h-4 w-4 shrink-0" />
                <span className="text-center md:text-right">
                  {s.address || "Agartala, Tripura, India"}
                  {(s.pinCode || !s.address) && (
                    <>
                      <br />
                      Pin: {s.pinCode || "799006"}
                    </>
                  )}
                </span>
              </li>
              <li className="flex items-center justify-center gap-2 md:justify-end">
                <Phone className="h-4 w-4 shrink-0" />
                <a
                  href={`tel:${(s.contactPhone || "+91 99999 99999").replace(/\s+/g, "")}`}
                  className="hover:text-foreground hover:underline"
                >
                  {s.contactPhone || "+91 99999 99999"}
                </a>
              </li>
              <li className="flex items-center justify-center gap-2 md:justify-end">
                <Mail className="h-4 w-4 shrink-0" />
                <a
                  href={`mailto:${s.contactEmail || "contact@todaytripura.com"}`}
                  className="hover:text-foreground hover:underline"
                >
                  {s.contactEmail || "contact@todaytripura.com"}
                </a>
              </li>
            </ul>
          </div>
        </div>

        {/* Bottom Card Container */}
        <div className="mt-6 flex flex-col items-center justify-between gap-2.5 rounded-xl border border-border/80 bg-muted/40 px-3.5 sm:px-5 py-3 text-xs text-muted-foreground shadow-xs md:flex-row">
          <p className="font-medium text-center md:text-left whitespace-nowrap text-[10.5px] min-[360px]:text-[11.5px] sm:text-xs tracking-tight sm:tracking-normal overflow-hidden text-ellipsis max-w-full">
            {copyright}
          </p>

          <p className="flex flex-wrap items-center justify-center gap-1.5 md:justify-end text-[11px] sm:text-xs">
            <span>{t("footer.builtBy")}:</span>
            <a
              id="gorilla-tech-partner-tag"
              href="https://gorillatechsolution.com"
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center rounded-md bg-[#0F2042] px-2.5 py-1 text-[11px] font-bold uppercase tracking-wider text-white shadow-xs transition-all hover:bg-[#1E3A8A] hover:shadow-sm shrink-0"
            >
              GORILLA TECH SOLUTION
            </a>
          </p>
        </div>
      </div>
      {/* <AttributionGuard /> */}
    </footer>
  );
}

export default Footer;
